30: function openModal(title,desc,options,foot='Take your time. There is no wrong way to spend a day.'){$('#modalRoot').innerHTML=`<div class="modal-backdrop"><div class="modal"><div class="modal-top"><div><div class="eyebrow">A MOMENT TO YOURSELF</div><h2>${title}</h2><p>${desc}</p></div><button class="modal-close" aria-label="Close">×</button></div><div class="modal-options">${options.map((o,i)=>`<button class="option" data-opt="${i}" ${o.disabled?'disabled':''} style="${o.disabled?'opacity:.48;cursor:default':''}"><span class="option-emoji">${o.emoji}</span><span class="option-copy"><b>${o.name}</b><small>${o.desc}</small></span><span class="option-cost">${o.cost||'↗'}</span></button>`).join('')}</div><div class="modal-foot"><span>${foot}</span><strong>✦ ${game.points} drops</strong></div></div></div>`;$('#modalRoot .modal-close').onclick=closeModal;$('#modalRoot .modal-backdrop').onclick=e=>{if(e.target.classList.contains('modal-backdrop'))closeModal()};$$('#modalRoot .option').forEach(b=>b.onclick=()=>{let o=options[+b.dataset.opt];if(!o.disabled)o.run()})}
