33: function cook(){openModal('What sounds good?','The kitchen is sunny, and you have just enough time to make something lovely.',recipes.map(r=>({emoji:r.emoji,name:r.name,desc:r.desc,cost:canPay(r.cost)?Object.entries(r.cost).map(([k,v])=>`${v} ${k}`).join(' · '):'You need '+Object.keys(r.cost).filter(k=>(game.inventory[k]||0)<r.cost[k]).join(', '),disabled:!canPay(r.cost),run:()=>{if(!spend())return;consume(r.cost);game.inventory['Cat food']=(game.inventory['Cat food']||0)+1;game.points+=r.reward;complete(r.task);toast(`${r.name} made! A little portion saved for ${game.cats[game.cat].name}. +${r.reward} drops`);closeModal();save()}})),'Cooking takes 1 energy · a little extra is tucked away for your cat.')}
34: function act(label){switch(label){case'Cook':return cook();case'Coffee':return drink();case'Chop wood':return chop();case'Movie night':return movie();case'Decorate':return decorate();case'Plant seeds':return plant();case'Harvest':return harvest();case'Tend garden':return tend();case'Forage':return forage();case'Look for cats':return explore();case'Gather wood':return chop();case'Shop supplies':return shop('supplies');case'Shop plants':return shop('plants');case'Shop home':return shop('home');case'Meet cats':return shop('cats');case'Projector night':return movie(true);case'Light firepit':return fire();case'Make s’mores':return smores();}}
35: function drink(){openModal('A little coffee ritual','A specialty iced espresso, the signature drink of Pinecone Cabin.',[{emoji:'🧋',name:'Honey oat iced espresso',desc:'A double shot over ice with honey & oat milk.',cost:canPay({Beans:1})?'1 coffee bean':'Need coffee beans',disabled:!canPay({Beans:1}),run:()=>{if(!spend())return;consume({Beans:1});game.points+=14;complete('drink');toast('Iced espresso, just right. +14 dew drops');closeModal();save()}},{emoji:'☕',name:'Pour-over, slow & easy',desc:'A simple warm cup for a thoughtful morning.',cost:canPay({Beans:1})?'1 coffee bean':'Need coffee beans',disabled:!canPay({Beans:1}),run:()=>{if(!spend())return;consume({Beans:1});toast('A warm cup, and nowhere else to be.');closeModal();save()}}])}
36: function chop(){openModal('A little wood for later','The chopping block is dry. One good bundle is plenty.',[{emoji:'🪓',name:'Chop a bundle of firewood',desc:'Good for a chilly evening or a glowing firepit.',cost:'1 energy',run:()=>{if(!spend())return;game.inventory.Wood=(game.inventory.Wood||0)+2;complete('fire');toast('Two neat bundles for the woodpile.');closeModal();save()}}])}
37: function plant(){openModal('What shall we grow?','A small seed becomes a whole season of good things.',[{emoji:'🍅',name:'Plant tomatoes',desc:'Sweet little tomatoes · 2 days to grow.',cost:canPay({Seeds:1})?'1 seed':'1 seed (buy some at the market)',disabled:!canPay({Seeds:1}),run:()=>{if(!spend())return;consume({Seeds:1});game.plants.push({name:'Tomato',day:game.day+2,emoji:'🍅'});complete('garden');toast('Tomatoes planted. Give them a couple of sunny days.');closeModal();save()}},{emoji:'🥕',name:'Plant carrots',desc:'Crunchy carrots · 1 day to grow.',cost:canPay({Seeds:1})?'1 seed':'1 seed (buy some at the market)',disabled:!canPay({Seeds:1}),run:()=>{if(!spend())return;consume({Seeds:1});game.plants.push({name:'Carrot',day:game.day+1,emoji:'🥕'});complete('garden');toast('A row of carrots, tucked into the soil.');closeModal();save()}}])}
38: function harvest(){let ready=game.plants.filter(p=>p.day<=game.day);if(!ready.length){toast(game.plants.length?'Not quite ready yet. Give them a little more time 🌱':'Nothing to pick just yet. Try planting seeds!');return}if(!spend())return;ready.forEach(p=>{game.inventory[p.name]=(game.inventory[p.name]||0)+2;game.plants.splice(game.plants.indexOf(p),1)});game.stats=game.stats||{};game.stats.harvests=(game.stats.harvests||0)+ready.length;complete('garden');if(game.stats.harvests>=8)announceAchievement('green-thumb','Green Thumb','Gathered eight garden harvests');toast('A lovely harvest, fresh from your garden!');save()}
39: function tend(){if(!spend())return;game.plants.forEach(p=>p.day=Math.max(game.day,p.day-1));game.inventory.Herbs=(game.inventory.Herbs||0)+1;complete('garden');toast('You pulled a few weeds and snipped some herbs 🌿');save()}
