111: function tickWalk(dt) {
112:   const p = playerPosition();
113:   if (p.tx == null) { p.walking = false; return; }
114:   const dx = p.tx - p.x, dy = p.ty - p.y;
115:   const d = Math.hypot(dx, dy);
116:   const step = Math.min(0.18 * dt, d);
117:   if (d < 1.5) {
118:     p.x = p.tx; p.y = p.ty;
119:     delete p.tx; delete p.ty;
120:     p.walking = false;
121:     if (p.auto) { delete p.auto; interact(); }
122:     save();
123:     return;
124:   }
125:   p.x += dx / d * step;
126:   p.y += dy / d * step;
127:   p.walking = true;
128:   if (Math.abs(dx) > 1) p.face = dx < 0 ? -1 : 1;
129: }
